counts={'fully_met':sum(t['status']=='pass' for t in themes),'partial':sum(t['status']=='partial' for t in themes),'missed':sum(t['status']=='missed' for t in themes),'themes':len(themes),'full_records':len(records),'accessible_records':len(gold['expected_records']),'source_calls':trace['source_calls'],'requests':trace['requests'],'cache_hits':trace['cache_hits'],'remaining_source_calls':receipt['counts']['source_calls_remaining'],'remaining_requests':receipt['counts']['requests_remaining'],'completed_contexts':len(contexts),'unfinished_contexts':len(plan['unopened_contexts']),'completed_source_window_sweeps':len(sweeps),'unread_surfaced_records':len(plan['unread_surfaced_records']),'unchecked_attachments':len(plan['unchecked_attachments']),'exact_spans':provenance['quote_count'],'submitted_spans':sum(len(c['evidence']) for c in review['claims']),'completion_receipt_valid':provenance['completion_receipt_valid'],'validation_flags':len(provenance['errors']),'disposition_records':provenance['disposition_records'],'attribution_chains':provenance['attribution_chains'],'writing_packet_calls':sum(e['tool']=='writing_packet' for e in events),'save_notes_calls':sum(e['tool']=='save_notes' for e in events),'saved_notes':len(review['evidence_notes']),'material_notes':provenance['material_notes'],'material_notes_represented':provenance['material_notes_represented'],'explicit_material_exclusions':len(review['omitted_material']),'partial_coverage_notes':len(review['partial_coverage_notes']),'narrative_claims':len(review['claims']),'rejection_only_records':len(provenance['rejection_only_records']),'source_credit_records':provenance['source_credit_records'],'draft_checks':sum(e['tool']=='draft_check' for e in events),'failed_draft_checks':sum(e['tool']=='draft_check' and not e['result'].get('valid') for e in events)}
